import java.util.HashMap;
import java.util.Map;
import java.util.Scanner;

public class Main {
    private static Map<Long, Long> memo = new HashMap<>();

    public static long computeValue(long n) {
        if (memo.containsKey(n)) {
            return memo.get(n);
        }
        if (n <= 11) {
            long result = Math.min(n, 2 + (11 - n));
            memo.put(n, result);
            return result;
        }
        long base = 1;
        long depth = 1;
        while (base <= n) {
            base = base * 10 + 1;
            depth++;
        }
        long limit = base / 10;
        long optionA, optionB;
        if (base > 2 * n) {
            long times = n / limit;
            long rem = n % limit;
            optionA = computeValue(base - n) + depth;
            optionB = times * (depth - 1) + computeValue(rem);
            long result = Math.min(optionA, optionB);
            memo.put(n, result);
            return result;
        } else {
            long times = n / limit;
            long rem = n % limit;
            optionA = computeValue(base - n) + depth;
            optionB = times * (depth - 1) + computeValue(rem);
            long result = Math.min(optionA, optionB);
            memo.put(n, result);
            return result;
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        long num = scanner.nextLong();
        System.out.println(computeValue(num));
        scanner.close();
    }
}
